def justify(words, width):
    if not words:
        return []

    lines = []
    current = []
    current_len = 0

    for word in words:
        if not current:
            current.append(word)
            current_len = len(word)
        else:
            # Adding word requires len(current) spaces between all words
            if current_len + len(current) + len(word) <= width:
                current.append(word)
                current_len += len(word)
            else:
                lines.append(_justify_line(current, width))
                current = [word]
                current_len = len(word)

    # Last line is left-justified
    if current:
        line = ' '.join(current)
        lines.append(line + ' ' * (width - len(line)))

    return lines


def _justify_line(words, width):
    if len(words) == 1:
        return words[0] + ' ' * (width - len(words[0]))

    total_len = sum(len(w) for w in words)
    total_spaces = width - total_len
    gaps = len(words) - 1

    base = total_spaces // gaps
    extra = total_spaces % gaps

    parts = []
    for i, word in enumerate(words):
        parts.append(word)
        if i < gaps:
            spaces = base + (1 if i < extra else 0)
            parts.append(' ' * spaces)

    return ''.join(parts)
